package zdex

import "chain"

// Launch is disabled. Existing launched pools still trade; ClaimVest still works.
func Launch(cur realm, name, symbol string, decimals, totalSupply, creatorKeepBps, virtualUgnot, vestBlocks, lockBlocks, snipeBlocks, snipeMaxBps int64) string {
	panic("zdex: launch disabled")
}

// launchLegacy keeps the bonding-curve path for tests and already-minted pools.
func launchLegacy(cur realm, name, symbol string, decimals, totalSupply, creatorKeepBps, virtualUgnot, vestBlocks, lockBlocks, snipeBlocks, snipeMaxBps int64) string {
	assertNotPaused()
	require(cur.Previous().IsUserCall(), "zdex: EOA only")
	require(totalSupply > minLiquidity, "zdex: supply too small")
	require(virtualUgnot > 0, "zdex: virtualUgnot")
	require(creatorKeepBps >= 0 && creatorKeepBps <= maxCreatorKeepBps, "zdex: creator keep")
	require(decimals >= 0 && decimals <= 18, "zdex: decimals")
	require(tryPool(poolIDFor(symbol)) == nil, "zdex: pool exists")

	if creatorKeepBps > 0 && vestBlocks < minVestBlocks {
		vestBlocks = minVestBlocks
	}
	if lockBlocks < minLockBlocks {
		lockBlocks = minLockBlocks
	}
	if snipeBlocks <= 0 {
		snipeBlocks = defaultSnipeBlocks
	}
	if snipeMaxBps <= 0 {
		snipeMaxBps = defaultSnipeMaxBps
	}
	require(snipeMaxBps <= maxSnipeMaxBps, "zdex: snipe max")

	creator := cur.Previous().Address()
	keep := MulDiv(totalSupply, creatorKeepBps, bpsDen)
	poolAmt := totalSupply - keep
	require(poolAmt > minLiquidity, "zdex: pool seed too small")

	key := mintInternal(cur, name, symbol, decimals, totalSupply, cur.Address())

	h := height()
	if keep > 0 {
		vests.Set(vestKey(symbol, creator), &Vesting{
			Symbol: symbol,
			Owner:  creator,
			Total:  keep,
			StartH: h,
			EndH:   h + vestBlocks,
		})
	}

	id := poolIDFor(symbol)
	// Burned (unowned) LP so TotalLP > 0: after unlock, others can add.
	// Nobody holds a Position for this seed, so it cannot be withdrawn.
	lp := geoMean(virtualUgnot, poolAmt)
	require(lp > minLiquidity, "zdex: tiny launch LP")
	p := &Pool{
		ID:           id,
		Token:        key,
		Symbol:       symbol,
		Name:         name,
		ReserveU:     0,
		ReserveT:     poolAmt,
		VirtualU:     virtualUgnot,
		TotalLP:      lp,
		FeeBps:       launchFeeBps,
		Creator:      creator,
		CreatorBps:   launchCreatorFeeBps,
		ProtocolBps:  launchProtocolFeeBps,
		Decimals:     decimals,
		UnlockHeight: h + lockBlocks,
		SnipeUntil:   h + snipeBlocks,
		SnipeMaxBps:  snipeMaxBps,
		Launched:     true,
		Internal:     true,
	}
	pools.Set(id, p)

	chain.Emit("Launch",
		"pool", id,
		"symbol", symbol,
		"token", key,
		"supply", itoa(totalSupply),
		"keep", itoa(keep),
		"virtual", itoa(virtualUgnot),
		"lp", itoa(lp),
		"creator", creator.String(),
	)
	return id
}

// ClaimVest releases linearly vested creator tokens.
func ClaimVest(cur realm, symbol string) int64 {
	assertNotPaused()
	owner := cur.Previous().Address()
	v := vests.Get(vestKey(symbol, owner))
	require(v != nil, "zdex: no vesting")
	vs := v.(*Vesting)
	rel := vestedAmount(vs, height())
	delta := rel - vs.Claimed
	require(delta > 0, "zdex: nothing to claim")
	vs.Claimed = rel
	pushToken(0, cur, symbol, owner, delta)
	chain.Emit("ClaimVest", "symbol", symbol, "to", owner.String(), "amount", itoa(delta))
	return delta
}

func vestedAmount(vs *Vesting, h int64) int64 {
	if h <= vs.StartH {
		return 0
	}
	if vs.EndH <= vs.StartH || h >= vs.EndH {
		return vs.Total
	}
	return MulDiv(vs.Total, h-vs.StartH, vs.EndH-vs.StartH)
}

func VestingOf(symbol string, owner address) (total, claimed, releasable int64) {
	v := vests.Get(vestKey(symbol, owner))
	if v == nil {
		return 0, 0, 0
	}
	vs := v.(*Vesting)
	rel := vestedAmount(vs, height())
	return vs.Total, vs.Claimed, rel - vs.Claimed
}

package zdex

import "chain"

const (
	listPending  = int64(0)
	listApproved = int64(1)
	listRejected = int64(2)
	maxLogoURI   = 128
)

type Listing struct {
	TokenKey  string
	Symbol    string
	Name      string
	Decimals  int64
	LogoURI   string
	Requester address
	Deposit   int64
	Status    int64
}

func isStableSym(s string) bool {
	return s == "USDC" || s == "USDT" || s == "DAI"
}

func tryListing(symbol string) *Listing {
	v := listings.Get(symbol)
	if v == nil {
		return nil
	}
	return v.(*Listing)
}

func requireListed(symbol string) {
	l := tryListing(symbol)
	require(l != nil && l.Status == listApproved, "zdex: not listed")
}

func upsertApprovedListing(symbol, name, tokenKey string, decimals int64, who address) {
	listings.Set(symbol, &Listing{
		TokenKey:  tokenKey,
		Symbol:    symbol,
		Name:      name,
		Decimals:  decimals,
		Requester: who,
		Status:    listApproved,
	})
}

func cleanLogo(s string) string {
	out := ""
	n := 0
	for i := 0; i < len(s) && n < maxLogoURI; i++ {
		c := s[i]
		if c == ';' || c == '\n' || c == '\r' {
			continue
		}
		out += s[i : i+1]
		n++
	}
	return out
}

// RequestListing posts a token for admin review. Caller sends exactly 1 GNOT.
// Approved tokens may CreatePool and appear in the UI catalog. Reject refunds.
func RequestListing(cur realm, tokenKey, symbol, name string, decimals int64, logoURI string) string {
	assertNotPaused()
	require(cur.Previous().IsUserCall(), "zdex: EOA only")
	require(symbol != "" && symbol != "GNOT" && symbol != nativeDenom, "zdex: symbol")
	require(decimals >= 0 && decimals <= 18, "zdex: decimals")
	prev := tryListing(symbol)
	require(prev == nil || prev.Status == listRejected, "zdex: listing exists")
	takeUgnot(cur, minListUgnot)
	caller := cur.Previous().Address()
	if name == "" {
		name = symbol
	}
	listings.Set(symbol, &Listing{
		TokenKey:  tokenKey,
		Symbol:    symbol,
		Name:      name,
		Decimals:  decimals,
		LogoURI:   cleanLogo(logoURI),
		Requester: caller,
		Deposit:   minListUgnot,
		Status:    listPending,
	})
	chain.Emit("RequestListing", "symbol", symbol, "from", caller.String())
	return symbol
}

func ApproveListing(cur realm, symbol string) {
	mustOwner(cur)
	rejectStrayUgnot()
	l := tryListing(symbol)
	require(l != nil && l.Status == listPending, "zdex: not pending")
	dep := l.Deposit
	l.Status = listApproved
	l.Deposit = 0
	if dep > 0 {
		sendUgnot(0, cur, admin, dep)
	}
	chain.Emit("ApproveListing", "symbol", symbol)
}

func RejectListing(cur realm, symbol string) {
	mustOwner(cur)
	rejectStrayUgnot()
	l := tryListing(symbol)
	require(l != nil && l.Status == listPending, "zdex: not pending")
	dep := l.Deposit
	to := l.Requester
	l.Status = listRejected
	l.Deposit = 0
	if dep > 0 {
		sendUgnot(0, cur, to, dep)
	}
	chain.Emit("RejectListing", "symbol", symbol)
}

func ListingOf(symbol string) (status, decimals, deposit int64) {
	l := tryListing(symbol)
	if l == nil {
		return 0, 0, 0
	}
	return l.Status, l.Decimals, l.Deposit
}

func ListingSnapshot(symbol string) string {
	l := tryListing(symbol)
	if l == nil {
		return ""
	}
	return listingLine(l)
}

func ListingList() string {
	out := ""
	listings.Iterate("", "", func(_ string, v any) bool {
		if out != "" {
			out += "\n"
		}
		out += listingLine(v.(*Listing))
		return false
	})
	return out
}

func listingLine(l *Listing) string {
	st := l.Status
	dec := l.Decimals
	dep := l.Deposit
	line := l.Symbol + ";" + l.Name + ";" + l.TokenKey + ";"
	line += itoa(dec) + ";" + itoa(st) + ";" + itoa(dep) + ";" + l.Requester.String()
	return line + ";" + l.LogoURI
}

package zdex

import (
	"math/overflow"

	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/amm/v1"
)

// AMM formula lives in gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/amm/v1 so a later /v2 library can
// ship without touching LP, book, or points in this realm. These wrappers
// keep the v1 MsgCall/qeval names stable.

func MulDiv(a, b, d int64) int64 {
	return amm.MulDiv(a, b, d)
}

func Sqrt(n int64) int64 {
	return amm.Sqrt(n)
}

func MulDivCeil(a, b, d int64) int64 {
	return amm.MulDivCeil(a, b, d)
}

func AmountOut(amountIn, reserveIn, virtualIn, reserveOut, virtualOut, feeBps int64) int64 {
	return amm.AmountOut(amountIn, reserveIn, virtualIn, reserveOut, virtualOut, feeBps)
}

func AmountIn(amountOut, reserveIn, virtualIn, reserveOut, virtualOut, feeBps int64) int64 {
	return amm.AmountIn(amountOut, reserveIn, virtualIn, reserveOut, virtualOut, feeBps)
}

func geoMean(a, b int64) int64 {
	prod, ok := overflow.Mul64(a, b)
	if ok {
		return Sqrt(prod)
	}
	return MulDiv(Sqrt(a), Sqrt(b), 1)
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func add64(a, b int64) int64 {
	s, ok := overflow.Add64(a, b)
	if !ok {
		panic("zdex: add overflow")
	}
	return s
}

func sub64(a, b int64) int64 {
	if b > a {
		panic("zdex: sub underflow")
	}
	return a - b
}

type feeSplit struct {
	gross    int64
	net      int64
	lp       int64
	creator  int64
	protocol int64
}

func splitFee(amountIn, feeBps, creatorBps, protocolBps int64) feeSplit {
	if feeBps < 0 || feeBps >= 10000 {
		panic("zdex: feeBps out of range")
	}
	if creatorBps < 0 || protocolBps < 0 || creatorBps+protocolBps > 10000 {
		panic("zdex: fee share out of range")
	}
	fee := MulDiv(amountIn, feeBps, 10000)
	net := amountIn - fee
	creator := MulDiv(fee, creatorBps, 10000)
	protocol := MulDiv(fee, protocolBps, 10000)
	lp := fee - creator - protocol
	if lp < 0 {
		panic("zdex: fee split underflow")
	}
	return feeSplit{gross: amountIn, net: net, lp: lp, creator: creator, protocol: protocol}
}

package zdex

import "chain"

func maybeRollEpoch() {
	h := height()
	if epochBlocks <= 0 {
		epochBlocks = defaultEpochBlocks
	}
	if epoch == 0 {
		epoch = 1
		epochEnd = h + epochBlocks
		return
	}
	if h < epochEnd {
		return
	}
	carry := closedPot
	closedID = epoch
	closedPts = epochPts
	closedPot = epochPot
	epoch++
	epochPts = 0
	epochPot = carry
	epochEnd = h + epochBlocks
	chain.Emit("Epoch", "id", itoa(int64(epoch)), "closedPot", itoa(closedPot), "closedPts", itoa(closedPts))
}

func getScore(owner address) *Score {
	v := scores.Get(owner.String())
	if v == nil {
		s := &Score{}
		scores.Set(owner.String(), s)
		return s
	}
	return v.(*Score)
}

func syncScore(s *Score) {
	maybeRollEpoch()
	if s.EpochID == epoch {
		return
	}
	if s.EpochID == closedID {
		s.Closed = s.Epoch
	} else {
		s.Closed = 0
	}
	s.Epoch = 0
	s.EpochID = epoch
}

func addPoints(owner address, pts int64) {
	if pts <= 0 {
		return
	}
	maybeRollEpoch()
	s := getScore(owner)
	syncScore(s)
	s.Epoch = add64(s.Epoch, pts)
	s.Life = add64(s.Life, pts)
	epochPts = add64(epochPts, pts)
}

func harvestLP(p *Pool, owner address) {
	st := getPos(p.ID, owner)
	if st == nil || st.LP <= 0 {
		return
	}
	acc := MulDiv(st.LP, p.AccPoints, ptsScale)
	if acc > st.RewardDebt {
		addPoints(owner, acc-st.RewardDebt)
	}
	st.RewardDebt = acc
}

func creditSwapPoints(p *Pool, trader address, volU int64, fs feeSplit, ugnotSide bool) {
	_ = trader
	_ = volU
	if ugnotSide {
		p.AccruedCreatorU = add64(p.AccruedCreatorU, fs.creator)
		p.AccruedProtocolU = add64(p.AccruedProtocolU, fs.protocol)
	} else {
		p.AccruedCreatorT = add64(p.AccruedCreatorT, fs.creator)
		p.AccruedProtocolT = add64(p.AccruedProtocolT, fs.protocol)
	}
}

// HarvestPoints settles LP points for a pool without depositing. No extra stake.
func HarvestPoints(cur realm, poolID string) int64 {
	panic("zdex: epoch disabled")
}

func HarvestAll(cur realm) int64 {
	panic("zdex: epoch disabled")
}

func ClaimFeeShare(cur realm) int64 {
	panic("zdex: epoch disabled")
}

func PointsOf(owner address) (life, epochPtsUser, closedPtsUser int64) {
	v := scores.Get(owner.String())
	if v == nil {
		return 0, 0, 0
	}
	s := v.(*Score)
	if s.EpochID == epoch {
		return s.Life, s.Epoch, s.Closed
	}
	if s.EpochID == closedID {
		return s.Life, 0, s.Epoch
	}
	return s.Life, 0, 0
}

func ClaimableFeeShare(owner address) int64 {
	if closedID == 0 || closedPot <= 0 || closedPts <= 0 {
		return 0
	}
	v := scores.Get(owner.String())
	if v == nil {
		return 0
	}
	s := v.(*Score)
	if s.ClaimedID == closedID {
		return 0
	}
	closed := s.Closed
	if s.EpochID == closedID {
		closed = s.Epoch
	} else if s.EpochID != epoch {
		return 0
	}
	return MulDiv(closed, closedPot, closedPts)
}

func EpochInfo() (id, endH, pot, pts, cID, cPot, cPts int64) {
	return int64(epoch), epochEnd, epochPot, epochPts, int64(closedID), closedPot, closedPts
}

func SetEpochBlocks(cur realm, n int64) {
	mustOwner(cur)
	require(n >= 10, "zdex: epoch too short")
	epochBlocks = n
	h := height()
	if epoch > 0 && epochEnd > h+n {
		epochEnd = h + n
	}
}

func SetFeeShareBps(cur realm, bps int64) {
	mustOwner(cur)
	require(bps >= 0 && bps <= bpsDen, "zdex: fee share")
	feeShareBps = bps
}

package zdex

import (
	"chain"

	"gno.land/r/demo/defi/grc20reg"
)

// CreatePool seeds a two-sided ugnot/GRC20 pool. The GRC20 must already
// exist (external or internal). Caller sends `amountU` ugnot with the tx
// and must have approved this realm for `amountT` of the token.
func CreatePool(cur realm, tokenKey, symbol string, amountU, amountT, feeBps int64) string {
	assertNotPaused()
	require(cur.Previous().IsUserCall(), "zdex: EOA only")
	require(amountU > 0 && amountT > 0, "zdex: amounts")
	require(amountU >= minListUgnot, "zdex: min 1 GNOT")
	if feeBps == 0 {
		if isStableSym(symbol) {
			feeBps = feeTierStable
		} else {
			feeBps = defaultFeeBps
		}
	}
	require(validSwapFee(feeBps), "zdex: fee tier 1/5/30/100")
	require(symbol != "", "zdex: symbol")
	id := poolIDFor(symbol)
	require(tryPool(id) == nil, "zdex: pool exists")
	caller := cur.Previous().Address()
	if caller != admin {
		requireListed(symbol)
	}

	takeUgnot(cur, amountU)
	ref := tokenPullKey(tokenKey, symbol)
	pullUserToken(0, cur, ref, caller, amountT)

	lp := geoMean(amountU, amountT)
	require(lp > minLiquidity, "zdex: tiny LP")
	lpUser := lp - minLiquidity

	name := symbol
	decimals := int64(0)
	internal := tryTok(symbol) != nil
	if internal {
		rec := getTok(symbol)
		name = rec.token.GetName()
		decimals = int64(rec.token.GetDecimals())
	} else {
		t := grc20reg.Get(ref)
		require(t != nil, "zdex: unknown token")
		require(t.GetSymbol() == symbol, "zdex: symbol mismatch")
		name = t.GetName()
		decimals = int64(t.GetDecimals())
	}
	p := &Pool{
		ID:          id,
		Token:       ref,
		Symbol:      symbol,
		Name:        name,
		ReserveU:    amountU,
		ReserveT:    amountT,
		TotalLP:     lp,
		FeeBps:      feeBps,
		Creator:     caller,
		ProtocolBps: poolProtocolFeeBps,
		Decimals:    decimals,
		Internal:    internal,
	}
	pools.Set(id, p)
	setPos(id, caller, lpUser)
	if caller == admin {
		upsertApprovedListing(symbol, name, ref, decimals, caller)
	}

	chain.Emit("CreatePool", "pool", id, "lp", itoa(lpUser), "creator", caller.String())
	return id
}

// CreateTokenPool lists two GRC20s (no ugnot). amountQ is quote token, amountB is base.
func CreateTokenPool(cur realm, quoteSym, baseSym string, amountQ, amountB, feeBps int64) string {
	assertNotPaused()
	require(cur.Previous().IsUserCall(), "zdex: EOA only")
	rejectStrayUgnot()
	require(amountQ > 0 && amountB > 0, "zdex: amounts")
	if feeBps == 0 {
		if isStableSym(quoteSym) && isStableSym(baseSym) {
			feeBps = feeTierStable
		} else {
			feeBps = feeTierLow
		}
	}
	require(validSwapFee(feeBps), "zdex: fee tier 1/5/30/100")
	require(quoteSym != "" && baseSym != "" && quoteSym != baseSym, "zdex: pair")
	id := pairID(quoteSym, baseSym)
	require(tryPool(id) == nil, "zdex: pool exists")
	caller := cur.Previous().Address()
	qrec := tryTok(quoteSym)
	brec := tryTok(baseSym)
	require(qrec != nil && brec != nil, "zdex: unknown token")
	pullUserToken(0, cur, quoteSym, caller, amountQ)
	pullUserToken(0, cur, baseSym, caller, amountB)
	lp := geoMean(amountQ, amountB)
	require(lp > minLiquidity, "zdex: tiny LP")
	lpUser := lp - minLiquidity
	p := &Pool{
		ID:          id,
		Token:       baseSym,
		QuoteSym:    quoteSym,
		QuoteTok:    quoteSym,
		Symbol:      baseSym,
		Name:        brec.token.GetName(),
		ReserveU:    amountQ,
		ReserveT:    amountB,
		TotalLP:     lp,
		FeeBps:      feeBps,
		Creator:     caller,
		ProtocolBps: poolProtocolFeeBps,
		Decimals:    int64(brec.token.GetDecimals()),
		Internal:    true,
	}
	pools.Set(id, p)
	setPos(id, caller, lpUser)
	chain.Emit("CreatePool", "pool", id, "lp", itoa(lpUser), "creator", caller.String())
	return id
}

// AddLiquidity deposits ugnot (OriginSend) + token in pool ratio.
func AddLiquidity(cur realm, poolID string, amountU, maxToken, minLP int64) int64 {
	assertNotPaused()
	p := getPool(poolID)
	require(!p.Launched || height() >= p.UnlockHeight, "zdex: launch LP locked")
	require(p.ReserveT > 0 && p.TotalLP > 0, "zdex: empty pool")
	require(amountU > 0, "zdex: amountU")
	baseU := p.ReserveU
	if baseU == 0 {
		baseU = p.VirtualU
	}
	require(baseU > 0, "zdex: no ugnot base")
	if p.QuoteSym != "" {
		rejectStrayUgnot()
		pullUserToken(0, cur, p.QuoteTok, cur.Previous().Address(), amountU)
	} else {
		takeUgnot(cur, amountU)
	}

	tokenIn := MulDiv(amountU, p.ReserveT, baseU)
	require(tokenIn > 0, "zdex: tokenIn")
	require(tokenIn <= maxToken, "zdex: token slippage")

	caller := cur.Previous().Address()
	pullUserToken(0, cur, poolTokRef(p), caller, tokenIn)

	lp := MulDiv(amountU, p.TotalLP, baseU)
	require(lp > 0, "zdex: zero LP")
	require(lp >= minLP, "zdex: min LP")

	harvestLP(p, caller)
	p.ReserveU = add64(p.ReserveU, amountU)
	p.ReserveT = add64(p.ReserveT, tokenIn)
	p.TotalLP = add64(p.TotalLP, lp)
	curLP := int64(0)
	if existing := getPos(poolID, caller); existing != nil {
		curLP = existing.LP
	}
	setPos(poolID, caller, add64(curLP, lp))
	if st := getPos(poolID, caller); st != nil {
		st.RewardDebt = MulDiv(st.LP, p.AccPoints, ptsScale)
	}

	chain.Emit("AddLiquidity", "pool", poolID, "lp", itoa(lp), "provider", caller.String())
	return lp
}

// RemoveLiquidity burns LP and returns ugnot + token. Blocked on launched
// pools until UnlockHeight (and even then the minimum-liquidity lock remains).
func RemoveLiquidity(cur realm, poolID string, lp, minU, minT int64) (int64, int64) {
	assertNotPaused()
	rejectStrayUgnot()
	p := getPool(poolID)
	require(height() >= p.UnlockHeight, "zdex: LP locked")
	require(lp > 0, "zdex: lp")
	require(p.TotalLP > minLiquidity, "zdex: no LP")

	caller := cur.Previous().Address()
	st := getPos(poolID, caller)
	require(st != nil && st.LP >= lp, "zdex: insufficient LP")
	harvestLP(p, caller)

	outU := MulDiv(lp, p.ReserveU, p.TotalLP)
	outT := MulDiv(lp, p.ReserveT, p.TotalLP)
	require(outU >= minU && outT >= minT, "zdex: slippage")
	require(outU < p.ReserveU && outT < p.ReserveT, "zdex: would drain")

	p.ReserveU = sub64(p.ReserveU, outU)
	p.ReserveT = sub64(p.ReserveT, outT)
	p.TotalLP = sub64(p.TotalLP, lp)
	setPos(poolID, caller, st.LP-lp)
	if left := getPos(poolID, caller); left != nil {
		left.RewardDebt = MulDiv(left.LP, p.AccPoints, ptsScale)
	}

	if p.QuoteSym != "" {
		pushToken(0, cur, p.QuoteTok, caller, outU)
	} else {
		sendUgnot(0, cur, caller, outU)
	}
	pushToken(0, cur, poolTokRef(p), caller, outT)

	chain.Emit("RemoveLiquidity", "pool", poolID, "lp", itoa(lp), "provider", caller.String())
	return outU, outT
}

func PoolInfo(poolID string) (reserveU, reserveT, virtualU, totalLP, feeBps int64) {
	p := getPool(poolID)
	return p.ReserveU, p.ReserveT, p.VirtualU, p.TotalLP, p.FeeBps
}

func PositionOf(poolID string, owner address) int64 {
	st := getPos(poolID, owner)
	if st == nil {
		return 0
	}
	return st.LP
}

func PoolCount() int {
	return pools.Size()
}

