func yesno(v bool) string {
	if v {
		return "yes"
	}
	return "no"
}

package zdex

func connectPool(a, b string) *Pool {
	a = normTok(a)
	b = normTok(b)
	if a == "" || b == "" || a == b {
		return nil
	}
	if a == nativeDenom {
		return tryPool(poolIDFor(b))
	}
	if b == nativeDenom {
		return tryPool(poolIDFor(a))
	}
	return tryPool(pairID(a, b))
}

func otherLeg(p *Pool, tok string) string {
	if p == nil {
		return ""
	}
	if p.QuoteSym != "" {
		if isQuoteTok(p, tok) {
			return p.Symbol
		}
		if isBaseTok(p, tok) {
			return p.QuoteSym
		}
		return ""
	}
	if tok == nativeDenom || tok == "GNOT" {
		return p.Symbol
	}
	if tok == p.Symbol || tok == p.Token {
		return nativeDenom
	}
	return ""
}

func hopIsBuy(p *Pool, tokenIn string) bool {
	if p.QuoteSym != "" {
		return isQuoteTok(p, tokenIn)
	}
	return tokenIn == nativeDenom || tokenIn == "GNOT"
}

func hopSnipeOK(p *Pool, out int64, buy bool) bool {
	if height() >= p.SnipeUntil || p.SnipeMaxBps <= 0 {
		return true
	}
	base := p.ReserveU
	if buy {
		base = p.ReserveT
	}
	return out <= MulDiv(base, p.SnipeMaxBps, bpsDen)
}

func quoteHop(p *Pool, tokenIn string, amountIn int64) int64 {
	if p == nil || amountIn <= 0 {
		return 0
	}
	if p.QuoteSym != "" {
		if isQuoteTok(p, tokenIn) {
			return AmountOut(amountIn, p.ReserveU, 0, p.ReserveT, 0, p.FeeBps)
		}
		if !isBaseTok(p, tokenIn) {
			return 0
		}
		return AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
	}
	if tokenIn == nativeDenom || tokenIn == "GNOT" {
		return AmountOut(amountIn, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
	}
	if tokenIn != p.Symbol && tokenIn != p.Token {
		return 0
	}
	return AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
}

func hasHub(hubs []string, h string) bool {
	for i := 0; i < len(hubs); i++ {
		if hubs[i] == h {
			return true
		}
	}
	return false
}

func collectHubs(in, out string) []string {
	hubs := []string{nativeDenom, "USDC", "USDT", "DAI"}
	pools.Iterate("", "", func(_ string, v any) bool {
		p := v.(*Pool)
		h := otherLeg(p, in)
		if h != "" && h != in && h != out && !hasHub(hubs, h) {
			hubs = append(hubs, h)
		}
		return false
	})
	return hubs
}

func quoteVia(in, hub, out string, amountIn int64) (mid, got int64) {
	p1 := connectPool(in, hub)
	p2 := connectPool(hub, out)
	if p1 == nil || p2 == nil || p1.ID == p2.ID {
		return 0, 0
	}
	mid = quoteHop(p1, in, amountIn)
	if mid <= 0 || !hopSnipeOK(p1, mid, hopIsBuy(p1, in)) {
		return 0, 0
	}
	got = quoteHop(p2, hub, mid)
	if got <= 0 || !hopSnipeOK(p2, got, hopIsBuy(p2, hub)) {
		return 0, 0
	}
	return mid, got
}

// bestVia picks the 2-hop hub with the highest AmountOut (lowest combined fee+impact).
func bestVia(in, out string, amountIn int64) (hub string, mid, got int64) {
	hubs := collectHubs(in, out)
	for i := 0; i < len(hubs); i++ {
		h := hubs[i]
		if h == in || h == out {
			continue
		}
		m, g := quoteVia(in, h, out, amountIn)
		if g > got {
			hub, mid, got = h, m, g
		}
	}
	return hub, mid, got
}

func applyHopKeep(p *Pool, caller address, tokenIn string, amountIn int64) int64 {
	if p.QuoteSym == "" {
		if tokenIn == nativeDenom || tokenIn == "GNOT" {
			return swapBuyKeepT(p, caller, amountIn)
		}
		return swapSellKeepU(p, caller, amountIn)
	}
	out := quoteHop(p, tokenIn, amountIn)
	require(out > 0, "zdex: zero out")
	assertSnipe(p, out, hopIsBuy(p, tokenIn))
	fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
	if isQuoteTok(p, tokenIn) {
		p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
		creditSwapPoints(p, caller, 0, fs, true)
		p.ReserveT = sub64(p.ReserveT, out)
	} else {
		require(isBaseTok(p, tokenIn), "zdex: tokenIn")
		p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
		creditSwapPoints(p, caller, 0, fs, false)
		p.ReserveU = sub64(p.ReserveU, out)
	}
	emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	return out
}

package zdex

import (
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	admin        address
	pendingAdmin address
	paused       bool
	pools        avl.Tree
	pos     avl.Tree
	orders  avl.Tree
	vests   avl.Tree
	tokens  avl.Tree
	scores  avl.Tree
	modules avl.Tree // surface name -> pkg path; empty means this hub
	farms    avl.Tree // trusted farm realm address -> true
	farmPay  avl.Tree // farm address -> prepaid ugnot
	listings avl.Tree // symbol -> *Listing
	nextOrd  seqid.ID

	epoch        uint64
	epochEnd     int64
	epochPts     int64
	epochPot     int64
	epochBlocks  int64
	feeShareBps  int64
	closedID     uint64
	closedPts    int64
	closedPot    int64
)

func init(cur realm) {
	admin = cur.Previous().Address()
	epochBlocks = defaultEpochBlocks
	feeShareBps = defaultFeeShareBps
}

func thisAddr() address {
	return unsafe.CurrentRealm().Address()
}

func thisPkg() string {
	return unsafe.CurrentRealm().PkgPath()
}

func height() int64 {
	return runtime.ChainHeight()
}

func mustOwner(cur realm) {
	if cur.Previous().Address() != admin {
		panic("zdex: admin only")
	}
}

func assertNotPaused() {
	if paused {
		panic("zdex: paused")
	}
}

func poolIDFor(symbol string) string {
	return nativeDenom + "|" + symbol
}

func pairID(a, b string) string {
	require(a != "" && b != "" && a != b, "zdex: pair")
	if a < b {
		return a + "|" + b
	}
	return b + "|" + a
}

func isQuoteTok(p *Pool, tok string) bool {
	if p.QuoteSym == "" {
		return tok == nativeDenom || tok == "GNOT"
	}
	return tok == p.QuoteSym || tok == p.QuoteTok
}

func isBaseTok(p *Pool, tok string) bool {
	return tok == p.Symbol || tok == p.Token
}

func posKey(poolID string, owner address) string {
	return poolID + "/" + owner.String()
}

func vestKey(symbol string, owner address) string {
	return symbol + "/" + owner.String()
}

func getPool(id string) *Pool {
	v := pools.Get(id)
	if v == nil {
		panic("zdex: pool not found")
	}
	return v.(*Pool)
}

func tryPool(id string) *Pool {
	v := pools.Get(id)
	if v == nil {
		return nil
	}
	return v.(*Pool)
}

func getPos(poolID string, owner address) *Position {
	v := pos.Get(posKey(poolID, owner))
	if v == nil {
		return nil
	}
	return v.(*Position)
}

func setPos(poolID string, owner address, lp int64) {
	k := posKey(poolID, owner)
	if lp == 0 {
		pos.Remove(k)
		return
	}
	pos.Set(k, &Position{LP: lp})
}

func require(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

package zdex

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// Quote returns the token/ugnot the trader would receive for amountIn.
// tokenIn is "ugnot" or the pool symbol (or registry key).
func Quote(poolID, tokenIn string, amountIn int64) int64 {
	p := getPool(poolID)
	if isQuoteTok(p, tokenIn) {
		return AmountOut(amountIn, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
	}
	return AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
}

// QuoteIn returns the input needed so the trader receives at least amountOut
// of tokenOut ("ugnot" or the pool symbol).
func QuoteIn(poolID, tokenOut string, amountOut int64) int64 {
	p := getPool(poolID)
	if tokenOut == nativeDenom {
		return AmountIn(amountOut, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
	}
	return AmountIn(amountOut, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
}

func normTok(s string) string {
	if s == "" || s == "GNOT" || s == nativeDenom {
		return nativeDenom
	}
	return s
}

// QuoteRoute: GNOT 1-hop, or a direct TOKEN-TOKEN pool, else the 2-hop
// hub (GNOT / USDC / USDT / …) with the highest AmountOut.
func QuoteRoute(tokenIn, tokenOut string, amountIn int64) int64 {
	assertNotPaused()
	require(amountIn > 0, "zdex: amountIn")
	in := normTok(tokenIn)
	out := normTok(tokenOut)
	require(in != out, "zdex: same token")
	if in == nativeDenom {
		p := getPool(poolIDFor(out))
		got := Quote(p.ID, nativeDenom, amountIn)
		assertSnipe(p, got, true)
		return got
	}
	if out == nativeDenom {
		p := getPool(poolIDFor(in))
		got := Quote(p.ID, in, amountIn)
		assertSnipe(p, got, false)
		return got
	}
	if dp := tryPool(pairID(in, out)); dp != nil {
		got := Quote(dp.ID, in, amountIn)
		assertSnipe(dp, got, isQuoteTok(dp, in))
		return got
	}
	_, _, got := bestVia(in, out, amountIn)
	require(got > 0, "zdex: pool not found")
	return got
}

// QuoteRouteSnapshot: tokenIn;tokenOut;hops;mid;amountOut;hub
func QuoteRouteSnapshot(tokenIn, tokenOut string, amountIn int64) string {
	in := normTok(tokenIn)
	out := normTok(tokenOut)
	got := QuoteRoute(in, out, amountIn)
	hops := int64(1)
	mid := int64(0)
	hub := ""
	if in != nativeDenom && out != nativeDenom {
		if tryPool(pairID(in, out)) != nil {
			hops = 1
		} else {
			hops = 2
			hub, mid, got = bestVia(in, out, amountIn)
		}
	}
	line := in + ";" + out + ";" + itoa(hops) + ";" + itoa(mid) + ";" + itoa(got)
	if hub != "" {
		line += ";" + hub
	}
	return line
}

func assertDeadline(maxHeight int64) {
	if maxHeight > 0 {
		require(height() <= maxHeight, "zdex: expired")
	}
}

func assertSnipe(p *Pool, out int64, buy bool) {
	if height() >= p.SnipeUntil || p.SnipeMaxBps <= 0 {
		return
	}
	base := p.ReserveU
	if buy {
		base = p.ReserveT
	}
	capOut := MulDiv(base, p.SnipeMaxBps, bpsDen)
	require(out <= capOut, "zdex: snipe cap")
}

func emitSwap(p *Pool, trader address, tokenIn string, amountIn, amountOut, fee int64) {
	chain.Emit("Swap",
		"pool", p.ID,
		"trader", trader.String(),
		"tokenIn", tokenIn,
		"amountIn", itoa(amountIn),
		"amountOut", itoa(amountOut),
		"reserveU", itoa(p.ReserveU),
		"reserveT", itoa(p.ReserveT),
		"fee", itoa(fee),
	)
}

// SwapExactIn executes a swap against a ugnot/token pool.
// tokenIn is "ugnot" (pay with OriginSend) or the pool symbol/key.
// minOut is slippage protection; maxHeight is a deadline (0 = none).
func SwapExactIn(cur realm, poolID, tokenIn string, amountIn, minOut, maxHeight int64) int64 {
	assertNotPaused()
	require(amountIn > 0, "zdex: amountIn")
	require(minOut >= 0, "zdex: minOut")
	assertDeadline(maxHeight)

	p := getPool(poolID)
	if p.QuoteSym != "" {
		return swapExactInPair(cur, p, tokenIn, amountIn, minOut)
	}
	buy := tokenIn == nativeDenom
	caller := cur.Previous().Address()

	var out int64
	if buy {
		takeUgnot(cur, amountIn)
		out = AmountOut(amountIn, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
		require(out >= minOut, "zdex: slippage")
		assertSnipe(p, out, true)
		fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
		creditSwapPoints(p, caller, amountIn, fs, true)
		p.ReserveT = sub64(p.ReserveT, out)
		maybeGraduate(p)
		pushToken(0, cur, poolTokRef(p), caller, out)
		emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	} else {
		rejectStrayUgnot()
		require(tokenIn == p.Symbol || tokenIn == p.Token, "zdex: tokenIn")
		out = AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
		require(out >= minOut, "zdex: slippage")
		assertSnipe(p, out, false)
		pullUserToken(0, cur, poolTokRef(p), caller, amountIn)
		fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
		creditSwapPoints(p, caller, out, fs, false)
		p.ReserveU = sub64(p.ReserveU, out)
		sendUgnot(0, cur, caller, out)
		emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	}
	return out
}

func swapExactInPair(cur realm, p *Pool, tokenIn string, amountIn, minOut int64) int64 {
	rejectStrayUgnot()
	caller := cur.Previous().Address()
	var out int64
	if isQuoteTok(p, tokenIn) {
		out = AmountOut(amountIn, p.ReserveU, 0, p.ReserveT, 0, p.FeeBps)
		require(out >= minOut, "zdex: slippage")
		assertSnipe(p, out, true)
		pullUserToken(0, cur, p.QuoteTok, caller, amountIn)
		fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
		creditSwapPoints(p, caller, 0, fs, true)
		p.ReserveT = sub64(p.ReserveT, out)
		pushToken(0, cur, poolTokRef(p), caller, out)
		emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	} else {
		require(isBaseTok(p, tokenIn), "zdex: tokenIn")
		out = AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
		require(out >= minOut, "zdex: slippage")
		assertSnipe(p, out, false)
		pullUserToken(0, cur, poolTokRef(p), caller, amountIn)
		fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
		creditSwapPoints(p, caller, 0, fs, false)
		p.ReserveU = sub64(p.ReserveU, out)
		pushToken(0, cur, p.QuoteTok, caller, out)
		emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	}
	return out
}

func swapSellKeepU(p *Pool, caller address, amountIn int64) int64 {
	out := AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
	require(out > 0, "zdex: zero out")
	assertSnipe(p, out, false)
	fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
	p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
	creditSwapPoints(p, caller, out, fs, false)
	p.ReserveU = sub64(p.ReserveU, out)
	emitSwap(p, caller, p.Symbol, amountIn, out, fs.gross-fs.net)
	return out
}

func swapBuyKeepT(p *Pool, caller address, ugnotIn int64) int64 {
	out := AmountOut(ugnotIn, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
	require(out > 0, "zdex: zero out")
	assertSnipe(p, out, true)
	fs := splitFee(ugnotIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
	p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
	creditSwapPoints(p, caller, ugnotIn, fs, true)
	p.ReserveT = sub64(p.ReserveT, out)
	maybeGraduate(p)
	emitSwap(p, caller, nativeDenom, ugnotIn, out, fs.gross-fs.net)
	return out
}

// SwapRouteExactIn: direct TOKEN-TOKEN pool if it exists; else the 2-hop
// hub with the highest AmountOut. Intermediate stays in the realm banker.
func SwapRouteExactIn(cur realm, tokenIn, tokenOut string, amountIn, minOut, maxHeight int64) int64 {
	assertNotPaused()
	require(amountIn > 0, "zdex: amountIn")
	require(minOut >= 0, "zdex: minOut")
	assertDeadline(maxHeight)
	in := normTok(tokenIn)
	out := normTok(tokenOut)
	require(in != nativeDenom && out != nativeDenom, "zdex: use SwapExactIn")
	require(in != out, "zdex: same token")
	rejectStrayUgnot()
	if dp := tryPool(pairID(in, out)); dp != nil {
		return SwapExactIn(cur, dp.ID, in, amountIn, minOut, maxHeight)
	}
	hub, midQ, gotQ := bestVia(in, out, amountIn)
	require(gotQ > 0, "zdex: pool not found")
	require(gotQ >= minOut, "zdex: slippage")
	p1 := connectPool(in, hub)
	p2 := connectPool(hub, out)
	require(p1 != nil && p2 != nil, "zdex: pool not found")
	caller := cur.Previous().Address()
	pullUserToken(0, cur, in, caller, amountIn)
	mid := applyHopKeep(p1, caller, in, amountIn)
	require(mid == midQ, "zdex: route drifted")
	got := applyHopKeep(p2, caller, hub, mid)
	require(got >= minOut, "zdex: slippage")
	pushToken(0, cur, out, caller, got)
	chain.Emit("Route", "in", in, "out", out, "hub", hub, "amountIn", itoa(amountIn), "mid", itoa(mid), "outAmt", itoa(got))
	return got
}

// SwapExactOut pays as little as needed to receive amountOut of tokenOut.
// tokenOut is "ugnot" or the pool symbol. maxIn caps what the trader pays.
// Buying tokens: send at least the required ugnot; excess is refunded.
func SwapExactOut(cur realm, poolID, tokenOut string, amountOut, maxIn, maxHeight int64) int64 {
	assertNotPaused()
	require(amountOut > 0, "zdex: amountOut")
	require(maxIn > 0, "zdex: maxIn")
	assertDeadline(maxHeight)

	p := getPool(poolID)
	caller := cur.Previous().Address()
	buy := tokenOut != nativeDenom && tokenOut != ""

	if buy {
		require(tokenOut == p.Symbol || tokenOut == p.Token, "zdex: tokenOut")
		require(cur.Previous().IsUserCall(), "zdex: ugnot swap is EOA-only")
		in := AmountIn(amountOut, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
		require(in <= maxIn, "zdex: slippage")
		sent := originUgnot()
		require(sent >= in, "zdex: OriginSend mismatch")
		assertSnipe(p, amountOut, true)
		fs := splitFee(in, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
		creditSwapPoints(p, caller, in, fs, true)
		p.ReserveT = sub64(p.ReserveT, amountOut)
		maybeGraduate(p)
		pushToken(0, cur, poolTokRef(p), caller, amountOut)
		if sent > in {
			sendUgnot(0, cur, caller, sent-in)
		}
		emitSwap(p, caller, nativeDenom, in, amountOut, fs.gross-fs.net)
		return in
	}

	rejectStrayUgnot()
	in := AmountIn(amountOut, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
	require(in <= maxIn, "zdex: slippage")
	assertSnipe(p, amountOut, false)
	pullUserToken(0, cur, poolTokRef(p), caller, in)
	fs := splitFee(in, p.FeeBps, p.CreatorBps, p.ProtocolBps)
	p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
	creditSwapPoints(p, caller, amountOut, fs, false)
	p.ReserveU = sub64(p.ReserveU, amountOut)
	sendUgnot(0, cur, caller, amountOut)
	emitSwap(p, caller, p.Symbol, in, amountOut, fs.gross-fs.net)
	return in
}

func maybeGraduate(p *Pool) {
	if p.VirtualU <= 0 || p.ReserveU < p.VirtualU {
		return
	}
	p.VirtualU = 0
	chain.Emit("Graduate", "pool", p.ID, "reserveU", itoa(p.ReserveU))
}

func SpotPrice(poolID string) int64 {
	p := getPool(poolID)
	den := add64(p.ReserveU, p.VirtualU)
	if den <= 0 || p.ReserveT <= 0 {
		return 0
	}
	return MulDiv(p.ReserveT, 1_000_000, den)
}

func sendUgnot(_ int, rlm realm, to address, amount int64) {
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: nativeDenom, Amount: amount}})
}

func originUgnot() int64 {
	os := unsafe.OriginSend()
	if len(os) == 0 {
		return 0
	}
	require(len(os) == 1, "zdex: OriginSend denom")
	require(os[0].Denom == nativeDenom, "zdex: OriginSend denom")
	return os[0].Amount
}

func rejectStrayUgnot() {
	require(originUgnot() == 0, "zdex: unexpected ugnot")
}

func takeUgnot(cur realm, amount int64) {
	require(amount > 0, "zdex: amount")
	prev := cur.Previous()
	if prev.IsUserCall() {
		require(originUgnot() == amount, "zdex: OriginSend mismatch")
		return
	}
	k := prev.Address().String()
	require(farms.Has(k), "zdex: unknown farm")
	v := farmPay.Get(k)
	require(v != nil, "zdex: farm unpaid")
	have, ok := v.(int64)
	require(ok && have >= amount, "zdex: farm unpaid")
	if have == amount {
		farmPay.Remove(k)
	} else {
		farmPay.Set(k, have-amount)
	}
}

package zdex

import (
	"gno.land/p/demo/tokens/grc20"
	"gno.land/p/nt/seqid/v0"
	"gno.land/r/demo/defi/grc20reg"
)

type tokenRec struct {
	token  *grc20.Token
	ledger *grc20.PrivateLedger
}

var nextTok seqid.ID

func getTok(symbol string) *tokenRec {
	v := tokens.Get(symbol)
	if v == nil {
		panic("zdex: unknown token " + symbol)
	}
	return v.(*tokenRec)
}

func tryTok(symbol string) *tokenRec {
	v := tokens.Get(symbol)
	if v == nil {
		return nil
	}
	return v.(*tokenRec)
}

func mintInternal(cur realm, name, symbol string, decimals, amount int64, to address) string {
	require(tryTok(symbol) == nil, "zdex: symbol taken")
	require(decimals >= 0 && decimals <= 18, "zdex: decimals")
	tok, led := grc20.NewToken(name, symbol, int(decimals), nextTok.Next(), cur)
	if amount > 0 {
		checkErr(led.Mint(to, amount))
	}
	tokens.Set(symbol, &tokenRec{token: tok, ledger: led})
	return grc20reg.Register(cross(cur), tok, "")
}

func tokenPullKey(tokenKey, symbol string) string {
	if tryTok(symbol) != nil {
		return symbol
	}
	if tokenKey != "" {
		return tokenKey
	}
	return symbol
}

func poolTokRef(p *Pool) string {
	if p.Internal || p.Token == "" {
		return p.Symbol
	}
	return p.Token
}

func pullUserToken(_ int, rlm realm, symbol string, from address, amount int64) {
	require(amount > 0, "zdex: amount")
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	require(from == rlm.Previous().Address(), "zdex: from must be caller")
	rec := tryTok(symbol)
	if rec != nil {
		checkErr(rec.ledger.CallerTeller().Transfer(0, rlm, thisAddr(), amount))
		return
	}
	// Pearl grc20reg write wrappers are non-crossing: rlm must be this
	// realm's live cur. cross() would debit the registry instead.
	grc20reg.TransferFrom(0, rlm, symbol, from, thisAddr(), amount)
}

func pushToken(_ int, rlm realm, symbol string, to address, amount int64) {
	require(amount > 0, "zdex: amount")
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	rec := tryTok(symbol)
	if rec != nil {
		checkErr(rec.ledger.Transfer(thisAddr(), to, amount))
		return
	}
	grc20reg.Transfer(0, rlm, symbol, to, amount)
}

func tokenBalance(symbol string, owner address) int64 {
	rec := tryTok(symbol)
	if rec != nil {
		return rec.token.BalanceOf(owner)
	}
	t := grc20reg.Get(symbol)
	if t == nil {
		return 0
	}
	return t.BalanceOf(owner)
}

// Transfer moves an internally minted token. External GRC20s are transferred
// on their own realm.
func Transfer(cur realm, symbol string, to address, amount int64) {
	rec := getTok(symbol)
	checkErr(rec.ledger.CallerTeller().Transfer(0, cur, to, amount))
}

func Approve(cur realm, symbol string, spender address, amount int64) {
	rec := getTok(symbol)
	checkErr(rec.ledger.CallerTeller().Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, symbol string, from, to address, amount int64) {
	rec := getTok(symbol)
	checkErr(rec.ledger.CallerTeller().TransferFrom(0, cur, from, to, amount))
}

func BalanceOf(symbol string, owner address) int64 {
	return tokenBalance(symbol, owner)
}

func TotalSupply(symbol string) int64 {
	rec := tryTok(symbol)
	if rec == nil {
		t := grc20reg.Get(symbol)
		if t == nil {
			return 0
		}
		return t.TotalSupply()
	}
	return rec.token.TotalSupply()
}

func TokenKey(symbol string) string {
	rec := tryTok(symbol)
	if rec == nil {
		return ""
	}
	return rec.token.ID()
}

package zdex

import (
	"chain"

	"gno.land/p/nt/ufmt/v0"
)

// protoVersion is this realm generation. Gno packages are immutable:
// v2 is this path. A later /v3 ships as a new package; LP here stays.
// Admin points NextPkg / SetModule at the successor.
const protoVersion = "3"

const (
	modSwap   = "swap"
	modLP     = "lp"
	modCreate = "create"
	modBook   = "book"
	modPoints = "points"
	modQuote  = "quote"
	modAdmin  = "admin"
)

const defaultCaps = "swap;lp;create;quote;noStakeLp;route"

var nextPkg string

func validModule(name string) bool {
	return name == modSwap || name == modLP || name == modCreate ||
		name == modBook || name == modPoints || name == modQuote || name == modAdmin
}

func moduleNames() []string {
	return []string{modSwap, modLP, modCreate, modBook, modPoints, modQuote, modAdmin}
}

// Version is the ABI generation of this hub. v1 freeze: SwapExactIn,
// AddLiquidity, CreatePool, book, and points keep their names.
func Version() string {
	return protoVersion
}

// Caps is a semicolon-separated capability list so UIs feature-gate
// without coupling to a package path. Missing Caps on an older realm
// means the client should fall back to probing individual queries.
func Caps() string {
	return defaultCaps
}

// ThisPkg is the path of this hub realm.
func ThisPkg() string {
	return thisPkg()
}

// NextPkg is empty until admin points this generation at a successor.
// Liquidity and open orders stay in this package; the UI may switch
// new flow to NextPkg without rewriting swap/LP/points clients.
func NextPkg() string {
	return nextPkg
}

func SetNextPkg(cur realm, path string) {
	mustOwner(cur)
	nextPkg = path
	chain.Emit("NextPkg", "path", path)
}

// ModuleOf returns the package that currently owns a surface.
// Unmapped names resolve to this hub so a v2 book can move alone.
func ModuleOf(name string) string {
	if !validModule(name) {
		return thisPkg()
	}
	v := modules.Get(name)
	if v == nil {
		return thisPkg()
	}
	s, ok := v.(string)
	if !ok || s == "" {
		return thisPkg()
	}
	return s
}

func SetModule(cur realm, name, pkg string) {
	mustOwner(cur)
	require(validModule(name), "zdex: unknown module")
	if pkg == "" {
		modules.Remove(name)
	} else {
		modules.Set(name, pkg)
	}
	chain.Emit("SetModule", "name", name, "pkg", pkg)
}

// Modules is one surface per line: name;pkg
func Modules() string {
	out := ""
	for _, n := range moduleNames() {
		line := n + ";" + ModuleOf(n)
		if out != "" {
			out += "\n"
		}
		out += line
	}
	return out
}

// HubSnapshot is a single-line UI record:
// version;thisPkg;nextPkg;caps  (caps may contain further semicolons)
func HubSnapshot() string {
	return ufmt.Sprintf("%s;%s;%s;%s", Version(), thisPkg(), nextPkg, Caps())
}

package zdex

import "strconv"

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}
